mapper.insert:
INSERT INTO diet_checkin (
    user_id, checkin_date, meal_type, level, ratio, created_at, updated_at
) VALUES (
    #{userId}, #{checkinDate}, #{mealType}, #{level}, #{ratio}, #{createdAt}, #{updatedAt}
)
ON DUPLICATE KEY UPDATE
    level = VALUES(level),
    ratio = VALUES(ratio),
    updated_at = VALUES(updated_at)

mapper.select:
SELECT id, user_id, checkin_date, meal_type, level, ratio, created_at, updated_at
FROM diet_checkin
WHERE user_id = #{userId}
  AND checkin_date = #{checkinDate}
ORDER BY meal_type ASC
